import React, { useState, useEffect } from 'react';
import './App.css';
import NovaCore from './components/NovaCore/NovaCore';
import ModernChat from './components/Chat/ModernChat';
import SearchWidget from './components/Search/SearchWidget';
import NewsWidget from './components/News/NewsWidget';
import NotesWidget, { HiddenNotepadAccessButton } from './components/Notes/NotesWidget';
import TicTacToeWidget from './components/TicTacToe/TicTacToeWidget';
import CameraWidget from './components/Camera/CameraWidget';
import CalculatorWidget from './components/Calculator/CalculatorWidget';
import ObjectIdentificationWidget from './components/ObjectIdentification/ObjectIdentificationWidget';
import TaskWidget from './components/Task/TaskWidget';
import AIEyeWidget from './components/AIEye/AIEyeWidget';
import TimeWidget from '<div className="" />components/Time_Widget';
import FloatingChatButton from './components/Chat/FloatingChatButton';

function App() {
  const [chatOpen, setChatOpen] = useState(false);
  const [chatMinimized, setChatMinimized] = useState(false);
  const [widgets, setWidgets] = useState({
    search: true,
    news: true,
    notes: false,
    tictactoe: false,
    camera: false,
    calculator: false,
    objectidentification: false,
    task: false,
    aieye: false,
    time: false,
  });

  const handleChatToggle = () => {
    if (!chatOpen) {
      // Open chat if it's closed
      setChatOpen(true);
      setChatMinimized(false);
    } else if (chatMinimized) {
      // Restore if minimized
      setChatMinimized(false);
    } else {
      // Minimize if open
      setChatMinimized(true);
    }
  };

  const handleChatClose = () => {
    setChatOpen(false);
    setChatMinimized(false);
  };

  return (
    <div className="grid-container">
      {/* Background Elements */}
      <div className="dot-grid"></div>
      <div className="glow-overlay"></div>

      {/* Main Nova Interface */}
      <NovaCore />

      {/* Hidden Notepad Access Button (on left side) */}
      <HiddenNotepadAccessButton onOpen={() => toggleWidget('notes')} />

      {/* Chat Messages and Input */}
      <FloatingChatButton 
        isOpen={chatOpen && !chatMinimized} 
        onClick={handleChatToggle} 
      />
      <ModernChat
        isOpen={chatOpen}
        isMinimized={chatMinimized}
        onClose={handleChatClose}
        onMinimize={() => setChatMinimized(!chatMinimized)}
        onWidgetTrigger={toggleWidget}
      />

      {/* Widgets Container */}
      <div className="widgets-container">
        {widgets.search && <SearchWidget onClose={() => toggleWidget('search')} />}
        {widgets.news && <NewsWidget onClose={() => toggleWidget('news')} />}
        {widgets.notes && <NotesWidget onClose={() => toggleWidget('notes')} />}
        {widgets.tictactoe && <TicTacToeWidget onClose={() => toggleWidget('tictactoe')} />}
        {widgets.camera && <CameraWidget onClose={() => toggleWidget('camera')} />}
        {widgets.calculator && <CalculatorWidget onClose={() => toggleWidget('calculator')} />}
        {widgets.objectidentification && <ObjectIdentificationWidget onClose={() => toggleWidget('objectidentification')} />}
        {widgets.task && <TaskWidget onClose={() => toggleWidget('task')} />}
        {widgets.aieye && <AIEyeWidget onClose={() => toggleWidget('aieye')} />}
        {widgets.time && <TimeWidget isVisible={true} onClose={() => toggleWidget('time')} />}
      </div>
    </div>
  );
}

export default App;
